const postCard = (x) => `<article class="card"><div class="author">${av(x.author[0], 'sage', 44)}<div><b>${x.author}</b><div class="meta">в группе «${x.group}» · ${x.ago}</div></div></div><p>${x.text}</p><div class="row-btns" style="margin-top:4px">${btn('♡ ' + x.likes, { cls: 'btn-ghost btn-sm', attrs: S.role === 'guest' ? 'data-act="go" data-to="/login"' : 'data-act="toggle" data-msg-on="Демо: нравится" data-msg-off="Демо: отметка снята"' })}${btn('Комментарии · ' + x.comments, { cls: 'btn-ghost btn-sm', href: '#/groups/1' })}${btn('Написать автору', { cls: 'btn-ghost btn-sm', attrs: S.role === 'guest' ? 'data-act="go" data-to="/login"' : 'data-act="go" data-to="/me/messages/1"' })}</div></article>`;
const groupRow = (g) => `<div class="org">${av(g.letter, g.tone, 56)}<div><h3><a href="#/groups/${g.id}">${g.name}</a></h3><div class="meta">${g.open ? 'Открытая' : 'Закрытая — вступление по заявке'} · ${g.members} участников</div></div>${btn(g.open ? 'Вступить' : 'Подать заявку', { cls: 'btn-sm btn-secondary', attrs: S.role === 'guest' ? 'data-act="go" data-to="/login"' : demo(g.open ? 'Демо: вы в группе' : 'Демо: заявка отправлена владельцу группы') })}</div>`;
route('/community', { title: 'Сообщество', section: 'community', group: P, render: (p) => { const cur = p.q.get('tab') || 'feed';
  const b = { feed: () => `<div class="lst" style="max-width:720px">${S.role !== 'guest' ? `<div class="card"><button class="btn btn-secondary" style="width:100%;justify-content:flex-start" data-act="modal" data-id="post">${ic('plus', 'i-s')}Написать в группу…</button></div>` : ''}${DATA.posts.map(postCard).join('')}${btn('Показать ещё', { attrs: demo('Демо: подгружено ещё') })}</div>`,
    groups: () => `<div class="panel">${DATA.groups.map(groupRow).join('')}</div>`, polls: () => `<div class="comm">${pollPanel()}</div>`, issues: () => `<div class="comm">${DATA.issues.map(issuePanel).join('')}</div>` };
  return pageHead('Сообщество', { crumbs: [['Главная', '#/'], ['Сообщество']], sub: 'Лента групп, опросы и обращения жителей. Посты новых авторов сначала проверяет модератор.', actions: btn('Создать группу', { href: '#/me/groups?new=1', icon: 'plus' }) }) +
  `<div class="tabs" role="tablist">${comTabs.map(([v, t]) => `<a role="tab" href="#/community?tab=${v}" aria-selected="${v === cur}" style="padding:10px 14px;text-decoration:none;color:${v === cur ? 'var(--ink)' : 'var(--muted)'};border-bottom:2px solid ${v === cur ? 'var(--primary)' : 'transparent'}">${t}</a>`).join('')}</div>` + st(b[cur] || b.feed, ['Здесь пока тихо', 'Создайте группу или напишите первый пост.']); } });
MODALS.post = () => `<h2>Новый пост</h2><form data-form data-ok="Демо: пост отправлен на проверку модератору">${field('Группа', { type: 'select', opts: DATA.groups.map((g) => g.name) })}${field('Текст', { type: 'textarea', req: true, rows: 4 })}<div class="upload">${ic('image')}Фото — до 4 штук</div><div class="row-btns end">${btn('Отмена', { attrs: 'data-act="close"' })}${btn('Опубликовать', { type: 'submit', cls: 'btn-primary' })}</div></form>`;
route('/groups/:id', { title: 'Группа', section: 'community', group: P, sample: '/groups/1', render: (p) => { const g = DATA.groups.find((x) => x.id == p.id) || DATA.groups[0];
  return crumbs([['Сообщество', '#/community'], ['Группы', '#/community?tab=groups'], [g.name]]) + `<section class="card" style="display:flex;gap:16px;align-items:center;flex-wrap:wrap;margin:12px 0 20px">${av(g.letter, g.tone, 72)}<div style="flex:1;min-width:200px"><h1 tabindex="-1" style="font:600 32px var(--font-display);margin:0">${g.name}</h1><div class="meta">${g.open ? 'Открытая' : 'Закрытая'} группа · ${g.members} участников · ${g.about}</div></div>${btn(g.open ? 'Вступить' : 'Подать заявку', { cls: 'btn-primary', attrs: S.role === 'guest' ? 'data-act="go" data-to="/login"' : demo('Демо: готово') })}</section>
  ${g.open ? `<div class="lst" style="max-width:720px">${DATA.posts.map(postCard).join('')}<div class="card"><h3>Комментарии</h3><div class="author">${av('О', 'sun', 36)}<div><b>Ольга (пример)</b><p style="margin:2px 0">Есть «Бычье сердце», поделюсь.</p><div class="meta">20 мин · Ответить</div></div></div>${S.role !== 'guest' ? `<form data-form data-ok="Демо: комментарий опубликован" style="margin-top:12px">${field('Ваш комментарий', { req: true })}</form>` : `<p class="meta"><a href="#/login">Войдите</a>, чтобы комментировать.</p>`}</div></div>` : `<div class="gate">${ic('shield')}<h2>Закрытая группа</h2><p>Посты видят только участники. Заявку рассматривает владелец группы.</p></div>`}`; } });
route('/issues', { title: 'Обращения жителей', section: 'community', group: P, render: () => pageHead('Обращения жителей', { crumbs: [['Главная', '#/'], ['Обращения']], sub: 'Публичные обращения без имён авторов. По умолчанию обращения приватны и в администрацию автоматически не передаются.', actions: btn('Сообщить о проблеме', { href: '#/submit/issue', cls: 'btn-primary', icon: 'alert' }) }) + st(() => `<div class="comm">${DATA.issues.map(issuePanel).join('')}</div>`, ['Публичных обращений нет', 'Обращения публикуются, только если автор разрешил.']) });
route('/issues/:id', { title: 'Обращение', section: 'community', group: P, sample: '/issues/42', render: (p) => { const i = DATA.issues.find((x) => x.id == p.id) || DATA.issues[0]; return crumbs([['Обращения', '#/issues'], ['№ ' + i.id]]) + `<div class="detail" style="margin-top:12px"><article class="article"><span class="badge ${i.tone}">${i.status}</span><h1 tabindex="-1">${i.title}</h1><div class="meta">№ ${i.id} · ${i.ago} · автор скрыт</div><p>Описание проблемы демонстрационное. Место — текстом, карта — концепция.</p>${photo('sky')}</article><aside class="side">${issuePanel(i)}</aside></div>`; } });

