route('/submit/ad', { title: 'Новое объявление', need: ['resident'], group: SUBMIT, render: (p) => pageHead(p.q.get('edit') ? 'Редактирование объявления' : 'Новое объявление', { crumbs: [['Разместить', '#/submit'], ['Объявление']] }) + `<ol class="steps-h"><li class="on"><b>1</b>Описание</li><li><b>2</b>Фото</li><li><b>3</b>Проверка</li></ol>
<form class="form" data-form data-next="/submit/done">${field('Рубрика', { type: 'select', req: true, opts: ['Продам', 'Отдам даром', 'Услуги', 'Вакансия', 'Потеряно', 'Найдено'] })}${field('Заголовок', { req: true, ph: 'Например, детский велосипед', val: p.q.get('edit') ? 'Детская коляска' : '', help: 'До 80 символов' })}${field('Описание', { type: 'textarea', req: true, rows: 6 })}
<div class="form-2">${field('Цена, ₽', { type: 'number', help: 'Пусто — «по договорённости»' })}${field('Район', { type: 'select', opts: ['Октябрьский', 'Светлый'] })}</div><div class="upload">${ic('image')}<b>Добавьте фото</b><br>до 6 штук, JPG/PNG/WebP, до 10 МБ</div>
<div class="alert warn">${ic('clock')}<div>Вы новый автор — объявление проверит модератор, обычно в течение суток. После 3 одобренных публикаций — без проверки.</div></div><div class="row-btns">${btn('Отправить на проверку', { type: 'submit', cls: 'btn-primary btn-lg' })}${btn('Сохранить черновик', { attrs: demo('Демо: черновик сохранён') })}</div></form>` });
route('/submit/issue', { title: 'Сообщить о проблеме', need: ['resident'], group: SUBMIT, render: () => pageHead('Сообщить о проблеме', { crumbs: [['Разместить', '#/submit'], ['Обращение']], sub: 'Обращение получают сотрудники SVETLY. В администрацию оно автоматически не передаётся.' }) + `<form class="form" data-form data-next="/me/issues" data-ok="Демо: обращение № 43 принято">${field('Тема', { type: 'select', opts: ['Освещение', 'Дороги', 'Мусор', 'Вода и тепло', 'Другое'] })}${field('Что случилось', { req: true })}${field('Подробности и место', { type: 'textarea', req: true, rows: 5, help: 'Адрес или ориентир. Карта — концепция.' })}<div class="upload">${ic('image')}Фото, до 4 штук</div><label class="chk" style="display:flex;gap:10px"><input type="checkbox"> Показать обращение публично (без моего имени)</label>${btn('Отправить', { type: 'submit', cls: 'btn-primary btn-lg' })}</form>` });
route('/submit/org', { title: 'Заявка на размещение организации', need: ['resident'], group: SUBMIT, render: () => pageHead('Добавить организацию или услугу', { crumbs: [['Разместить', '#/submit'], ['Организация']], sub: 'Бесплатно. Карточку проверит администратор; после одобрения появится кабинет бизнеса.' }) + `<form class="form" data-form data-next="/submit/done?org=1">${field('Тип', { type: 'select', opts: ['Организация', 'Услуга частного мастера'] })}${field('Название', { req: true })}${field('Категория', { type: 'select', opts: DATA.cats })}${field('Описание', { type: 'textarea', rows: 4, req: true })}<div class="form-2">${field('Адрес', { help: 'Если есть' })}${field('Часы работы')}</div>${field('Телефон для жителей', { type: 'tel', help: 'Будет виден в карточке после проверки' })}${btn('Отправить заявку', { type: 'submit', cls: 'btn-primary btn-lg' })}</form>` });
route('/submit/done', { title: 'Отправлено на проверку', need: ['resident'], group: SUBMIT, render: (p) => `<div class="gate">${ic('clock')}<h1 tabindex="-1">Отправлено на проверку</h1><p>${p.q.get('org') ? 'Администратор проверит карточку. Решение появится в кабинете и в уведомлениях.' : 'Модератор проверит объявление, обычно в течение суток. Статус — в «Мои публикации».'}</p><div class="row-btns">${btn(p.q.get('org') ? 'К уведомлениям' : 'Мои публикации', { href: p.q.get('org') ? '#/me/notifications' : '#/me/pubs', cls: 'btn-primary' })}${btn('На главную', { href: '#/' })}</div></div>` });

/* служебные */
route('/404', { title: 'Страница не найдена', group: SUBMIT, render: () => `<div class="gate">${ic('sun')}<h1 tabindex="-1">Страница не найдена</h1><p>Возможно, адрес набран с ошибкой или запись снята с публикации.</p>${searchBox()}<div class="row-btns">${btn('На главную', { href: '#/', cls: 'btn-primary' })}</div></div>` });
route('/error', { title: 'Ошибка', group: SUBMIT, render: () => `<div class="gate">${ic('alert')}<h1 tabindex="-1">Что-то пошло не так</h1><p>Мы уже знаем об ошибке. Код запроса для поддержки: <code>req-7f3a</code> (пример).</p><div class="row-btns">${btn('Обновить страницу', { cls: 'btn-primary', attrs: demo('Демо: повтор') })}${btn('На главную', { href: '#/' })}</div></div>` });
route('/offline', { title: 'Нет соединения', group: SUBMIT, render: () => `<div class="gate">${ic('clock')}<h1 tabindex="-1">Нет соединения</h1><p>Сохранённые страницы недоступны офлайн: из соображений приватности кэшируется только оформление.</p>${btn('Повторить', { cls: 'btn-primary', attrs: demo('Демо: повтор') })}</div>` });
route('/states', { title: 'Состояния загрузки, пусто, ошибка', group: SUBMIT, render: () => pageHead('Состояния экранов', { sub: 'Любой список в прототипе можно переключить в верхней панели «Данные». Здесь — все три рядом.' }) + `<div class="tiles"><div class="tile w12"><h2>Загрузка</h2>${skeleton(2)}</div><div class="tile w6"><h2>Пусто</h2>${emptyBox('Объявлений пока нет', 'Станьте первым — это бесплатно.', btn('Подать объявление', { cls: 'btn-primary' }))}</div><div class="tile w6"><h2>Ошибка</h2>${errorBox()}</div><div class="tile w12"><h2>Модерация</h2><div class="status-row">${badge('Опубликовано', 'ok')}${badge('На проверке', 'warn')}${badge('Отклонено', 'err')}${badge('Срок истёк')}${badge('Новое', 'info')}${concept()}</div></div></div>` });

route('/screens', { title: 'Карта экранов', group: SUBMIT, render: () => { const g = {}; R.forEach((r) => { (g[r.group || 'Прочее'] ||= []).push(r); });
  return pageHead('Карта экранов прототипа', { sub: `Всего маршрутов: ${R.length}. Для закрытых разделов переключите роль в верхней панели.` }) + `<div class="screens">${Object.entries(g).map(([k, rs]) => `<h2>${k}</h2><div class="tbl-wrap"><table class="tbl"><thead><tr><th>Экран</th><th>Адрес</th><th>Доступ</th></tr></thead><tbody>${rs.map((r) => `<tr><td><a href="#${r.sample || r.path}">${r.title}</a></td><td data-l="Адрес"><code>#${r.sample || r.path}</code></td><td data-l="Доступ">${r.need ? r.need.map((x) => ROLES[x]).join(', ') : 'Все'}</td></tr>`).join('')}</tbody></table></div>`).join('')}</div>`; } });
